INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('claim_freq_high_risk', '同一用户3个月内理赔超过3次则标记为高风险', 'tag_high_risk', 'preset', '{"rule_id": "claim_freq_high_risk", "description_cn": "同一用户3个月内理赔超过3次则标记为高风险", "conditions": [{"entity": "claim", "field": "count_3m", "op": ">", "value": 3, "time_window": "3m"}], "action": "tag_high_risk", "action_params": {"risk_level": "high"}, "enabled": true, "priority": 10}', 10, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('policy_year_claim_reject', '同一保单年度内理赔次数 > 5次，暂停自动赔付。', 'reject', 'preset', '{"rule_id": "policy_year_claim_reject", "description_cn": "同一保单年度内理赔次数 > 5次，暂停自动赔付。", "conditions": [{"entity": "policy", "field": "year_claim_count", "op": ">", "value": 5, "time_window": "policy_year"}], "action": "reject", "action_params": {"reason": "policy_year_claim_reject"}, "enabled": true, "priority": 20}', 20, 1);
