INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('ip_freq_abnormal', '单日同一IP提交超过10次申请则标记异常', 'alert', 'preset', '{"rule_id": "ip_freq_abnormal", "description_cn": "单日同一IP提交超过10次申请则标记异常", "conditions": [{"entity": "ip", "field": "daily_submit_count", "op": ">", "value": 10, "time_window": "1d"}], "action": "alert", "action_params": {"reason": "ip_freq_abnormal"}, "enabled": true, "priority": 40}', 40, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('claim_premium_ratio_review', '单次理赔金额 / 年保费比例 > 10，触发专项复核。', 'manual_review', 'preset', '{"rule_id": "claim_premium_ratio_review", "description_cn": "单次理赔金额 / 年保费比例 > 10，触发专项复核。", "conditions": [{"entity": "claim", "field": "premium_ratio", "op": ">", "value": 10, "time_window": null}], "action": "manual_review", "action_params": {"reason": "claim_premium_ratio_review"}, "enabled": true, "priority": 50}', 50, 1);
