INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('card_multi_policy_alert', '同一银行卡被超过3个不同保单使用则预警', 'alert', 'preset', '{"rule_id": "card_multi_policy_alert", "description_cn": "同一银行卡被超过3个不同保单使用则预警", "conditions": [{"entity": "card", "field": "policy_count", "op": ">", "value": 3, "time_window": null}], "action": "alert", "action_params": {"reason": "card_multi_policy_alert"}, "enabled": true, "priority": 70}', 70, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('night_claim_manual', '夜间22点至次日6点提交的理赔自动转人工', 'manual_review', 'preset', '{"rule_id": "night_claim_manual", "description_cn": "夜间22点至次日6点提交的理赔自动转人工", "conditions": [{"entity": "claim", "field": "submit_hour", "op": "in", "value": [22, 23, 0, 1, 2, 3, 4, 5, 6], "time_window": null}], "action": "manual_review", "action_params": {"reason": "night_claim_manual"}, "enabled": true, "priority": 80}', 80, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('address_multi_high_policy_verify', '同一收货地址对应超过5份高额保单则核验', 'manual_review', 'preset', '{"rule_id": "address_multi_high_policy_verify", "description_cn": "同一收货地址对应超过5份高额保单则核验", "conditions": [{"entity": "address", "field": "high_policy_count", "op": ">", "value": 5, "time_window": null}], "action": "manual_review", "action_params": {"reason": "address_multi_high_policy_verify"}, "enabled": true, "priority": 90}', 90, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('id_no_apply_5_7d', '同一证件号在 7天 内提交投保申请 >= 5次，标记高风险并人工审核。', 'tag_high_risk', 'preset', '{"rule_id": "id_no_apply_5_7d", "description_cn": "同一证件号在 7天 内提交投保申请 >= 5次，标记高风险并人工审核。", "conditions": [{"entity": "id_no", "field": "policy_apply_count_7d", "op": ">=", "value": 5, "time_window": "7d"}], "action": "tag_high_risk", "action_params": {"risk_level": "high", "followup": "manual_review"}, "enabled": true, "priority": 11}', 11, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('phone_idno_link_verify_3', '同一手机号关联不同证件号 >= 3个，触发身份核验。', 'manual_review', 'preset', '{"rule_id": "phone_idno_link_verify_3", "description_cn": "同一手机号关联不同证件号 >= 3个，触发身份核验。", "conditions": [{"entity": "phone", "field": "distinct_idno_count", "op": ">=", "value": 3, "time_window": ""}], "action": "manual_review", "action_params": {"reason": "phone_idno_link_verify"}, "enabled": true, "priority": 12}', 12, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('device_apply_reject_24h_10', '同一设备指纹在 24小时 内提交申请 >= 10次，拒绝自动核保。', 'reject', 'preset', '{"rule_id": "device_apply_reject_24h_10", "description_cn": "同一设备指纹在 24小时 内提交申请 >= 10次，拒绝自动核保。", "conditions": [{"entity": "device", "field": "apply_count_24h", "op": ">=", "value": 10, "time_window": "24h"}], "action": "reject", "action_params": {"reason": "device_apply_reject_24h_10"}, "enabled": true, "priority": 13}', 13, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('insured_age75_cov1m_manual', '被保险人年龄 > 75 且保额 > 100万，强制人工核保。', 'manual_review', 'preset', '{"rule_id": "insured_age75_cov1m_manual", "description_cn": "被保险人年龄 > 75 且保额 > 100万，强制人工核保。", "conditions": [{"entity": "insured", "field": "age", "op": ">", "value": 75, "time_window": null}, {"entity": "policy", "field": "coverage_amount", "op": ">", "value": 1000000, "time_window": null}], "action": "manual_review", "action_params": {"reason": "insured_age75_cov1m_manual"}, "enabled": true, "priority": 14}', 14, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('address_high_new_30d_4', '短期内（30天）同一地址新增高额保单 >= 4份，触发反欺诈核查。', 'manual_review', 'preset', '{"rule_id": "address_high_new_30d_4", "description_cn": "短期内（30天）同一地址新增高额保单 >= 4份，触发反欺诈核查。", "conditions": [{"entity": "address", "field": "high_policy_new_count_30d", "op": ">=", "value": 4, "time_window": "30d"}], "action": "manual_review", "action_params": {"reason": "address_high_new_30d_4"}, "enabled": true, "priority": 15}', 15, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('policy_effective_claim_7d_review', '保单生效 <= 7天 即发生理赔，进入重点复核。', 'manual_review', 'preset', '{"rule_id": "policy_effective_claim_7d_review", "description_cn": "保单生效 <= 7天 即发生理赔，进入重点复核。", "conditions": [{"entity": "policy", "field": "days_from_effective_to_claim", "op": "<=", "value": 7, "time_window": "after_effective"}], "action": "manual_review", "action_params": {"reason": "policy_effective_claim_7d_review"}, "enabled": true, "priority": 16}', 16, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('night_claim_amount_manual', '夜间 22:00-06:00 提交理赔且金额 > 阈值，转人工审核。', 'manual_review', 'preset', '{"rule_id": "night_claim_amount_manual", "description_cn": "夜间 22:00-06:00 提交理赔且金额 > 阈值，转人工审核。", "conditions": [{"entity": "claim", "field": "submit_hour", "op": "in", "value": [22, 23, 0, 1, 2, 3, 4, 5, 6], "time_window": null}, {"entity": "claim", "field": "claim_amount", "op": ">", "value": 50000, "time_window": null}], "action": "manual_review", "action_params": {"reason": "night_claim_amount_manual", "amount_threshold_yuan": 50000}, "enabled": true, "priority": 17}', 17, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('claim_nlp_similar_cluster', '同一事故描述文本在多客户间高相似（NLP相似度高），标记团伙嫌疑。', 'tag_high_risk', 'preset', '{"rule_id": "claim_nlp_similar_cluster", "description_cn": "同一事故描述文本在多客户间高相似（NLP相似度高），标记团伙嫌疑。", "conditions": [{"entity": "claim", "field": "nlp_cross_customer_similarity", "op": ">=", "value": 0.85, "time_window": null}], "action": "tag_high_risk", "action_params": {"risk_level": "high", "tag": "nlp_cluster"}, "enabled": true, "priority": 18}', 18, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('payout_unrelated_first_high_review', '收款账户与投保人无关系且首次使用，且金额较高，触发复核。', 'manual_review', 'preset', '{"rule_id": "payout_unrelated_first_high_review", "description_cn": "收款账户与投保人无关系且首次使用，且金额较高，触发复核。", "conditions": [{"entity": "payout", "field": "unrelated_to_policyholder", "op": "==", "value": true, "time_window": null}, {"entity": "payout", "field": "first_use_account", "op": "==", "value": true, "time_window": null}, {"entity": "claim", "field": "claim_amount", "op": ">", "value": 100000, "time_window": null}], "action": "manual_review", "action_params": {"reason": "payout_unrelated_first_high_review"}, "enabled": true, "priority": 19}', 19, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('card_multi_customer_payout_30d', '同一银行卡在 30天 内被 >= 3 个客户用于赔付收款，触发预警。', 'alert', 'preset', '{"rule_id": "card_multi_customer_payout_30d", "description_cn": "同一银行卡在 30天 内被 >= 3 个客户用于赔付收款，触发预警。", "conditions": [{"entity": "card", "field": "distinct_customer_count_30d", "op": ">=", "value": 3, "time_window": "30d"}], "action": "alert", "action_params": {"reason": "card_multi_customer_payout_30d"}, "enabled": true, "priority": 21}', 21, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('payout_blacklist_network_block', '赔付账户历史命中黑名单关联网络，拦截并人工核验。', 'manual_review', 'preset', '{"rule_id": "payout_blacklist_network_block", "description_cn": "赔付账户历史命中黑名单关联网络，拦截并人工核验。", "conditions": [{"entity": "payout", "field": "blacklist_network_hit", "op": "==", "value": true, "time_window": null}], "action": "manual_review", "action_params": {"reason": "payout_blacklist_network_block"}, "enabled": true, "priority": 22}', 22, 1);
