INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('agent_early_loss_channel_alert_30d', '同一代理人名下保单早期出险率（30天）显著高于渠道均值 x%，预警。', 'alert', 'preset', '{"rule_id": "agent_early_loss_channel_alert_30d", "description_cn": "同一代理人名下保单早期出险率（30天）显著高于渠道均值 x%，预警。", "conditions": [{"entity": "agent", "field": "early_claim_rate_vs_channel_30d", "op": ">", "value": 1.2, "time_window": "30d"}], "action": "alert", "action_params": {"reason": "agent_early_loss_channel_alert_30d"}, "enabled": true, "priority": 24}', 24, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('channel_gbmi_anomaly_review', '某渠道短期内高保额低保费组合异常集中，触发渠道风控审查。', 'manual_review', 'preset', '{"rule_id": "channel_gbmi_anomaly_review", "description_cn": "某渠道短期内高保额低保费组合异常集中，触发渠道风控审查。", "conditions": [{"entity": "channel", "field": "gbmi_anomaly_index", "op": ">", "value": 0.6, "time_window": null}], "action": "manual_review", "action_params": {"reason": "channel_gbmi_anomaly_review"}, "enabled": true, "priority": 25}', 25, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('agent_template_input_qc', '代理人录入字段重复模板化明显（地址/职业异常一致），触发质检。', 'manual_review', 'preset', '{"rule_id": "agent_template_input_qc", "description_cn": "代理人录入字段重复模板化明显（地址/职业异常一致），触发质检。", "conditions": [{"entity": "agent", "field": "template_field_similarity", "op": ">", "value": 0.8, "time_window": null}], "action": "manual_review", "action_params": {"reason": "agent_template_input_qc"}, "enabled": true, "priority": 26}', 26, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('blacklist_multi_dim_hit_reject', '客户证件号/手机号/设备/IP 任一命中黑名单，直接转人工或拒绝。', 'reject', 'preset', '{"rule_id": "blacklist_multi_dim_hit_reject", "description_cn": "客户证件号/手机号/设备/IP 任一命中黑名单，直接转人工或拒绝。", "conditions": [{"entity": "blacklist", "field": "hit_any", "op": "==", "value": true, "time_window": null}], "action": "reject", "action_params": {"reason": "blacklist_multi_dim_hit_reject"}, "enabled": true, "priority": 27}', 27, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('fraud_graph_shared_points_2', '与已确证欺诈客户共享关键关系点（设备、地址、收款卡）>= 2 个，标记高风险。', 'tag_high_risk', 'preset', '{"rule_id": "fraud_graph_shared_points_2", "description_cn": "与已确证欺诈客户共享关键关系点（设备、地址、收款卡）>= 2 个，标记高风险。", "conditions": [{"entity": "graph", "field": "shared_risk_relation_points", "op": ">=", "value": 2, "time_window": ""}], "action": "tag_high_risk", "action_params": {"risk_level": "high", "tag": "fraud_graph"}, "enabled": true, "priority": 28}', 28, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('new_customer_graph_strong_limit', '新客户首次投保即与高风险关系图谱强关联，限制自动通过。', 'reject', 'preset', '{"rule_id": "new_customer_graph_strong_limit", "description_cn": "新客户首次投保即与高风险关系图谱强关联，限制自动通过。", "conditions": [{"entity": "user", "field": "high_risk_graph_association_score", "op": ">", "value": 0.75, "time_window": null}], "action": "reject", "action_params": {"reason": "new_customer_graph_strong_limit"}, "enabled": true, "priority": 29}', 29, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('ext_r001', '同一证件号在 3 日内同一渠道重复提交投保申请累计大于等于 8 次则标记可疑并转人工审核。', 'manual_review', 'preset', '{"rule_id": "ext_r001", "description_cn": "同一证件号在 3 日内同一渠道重复提交投保申请累计大于等于 8 次则标记可疑并转人工审核。", "conditions": [{"entity": "ext", "field": "m001", "op": ">=", "value": 1000000000000, "time_window": null}], "action": "manual_review", "action_params": {"catalog": "remark_ext_100", "rule_id": "ext_r001", "reason": "ext_r001", "summary": "同一证件号在 3 日内同一渠道重复提交投保申请累计大于等于 8 次则标记可疑并转人工审核。"}, "enabled": true, "priority": 401}', 401, 1);
INSERT INTO risk_rules (rule_id, description_cn, action, source, ir_json, priority, enabled) VALUES ('ext_r002', '同一手机号在 90 天内关联不同客户姓名超过 4 个则触发强化身份核验。', 'manual_review', 'preset', '{"rule_id": "ext_r002", "description_cn": "同一手机号在 90 天内关联不同客户姓名超过 4 个则触发强化身份核验。", "conditions": [{"entity": "ext", "field": "m002", "op": ">=", "value": 1000000000000, "time_window": null}], "action": "manual_review", "action_params": {"catalog": "remark_ext_100", "rule_id": "ext_r002", "reason": "ext_r002", "summary": "同一手机号在 90 天内关联不同客户姓名超过 4 个则触发强化身份核验。"}, "enabled": true, "priority": 402}', 402, 1);
